<script setup>
import {reactive,ref,computed,onMounted} from 'vue';import {useRecords} from '../stores/records.js';import {useFeedback} from '../stores/feedback.js';import Feedback from '../components/Feedback.vue';import RecordTable from '../components/RecordTable.vue';
const store=useRecords();const {busy,error,success,run}=useFeedback();const form=reactive({name:'',id:'',phone:'',zip:''});const query=ref(''),active=ref('');const results=computed(()=>store.students.filter(s=>[s.name,s.id].some(v=>v.toLowerCase().includes(active.value.toLowerCase()))));const columns=[{key:'name',label:'Name'},{key:'id',label:'Student ID'},{key:'phone',label:'Phone'},{key:'zip',label:'ZIP code'}];onMounted(()=>run(()=>store.loadStudents()));function search(){run(async()=>{await store.loadStudents();active.value=query.value.trim();});}function add(){run(async()=>{await store.addStudent({...form});Object.keys(form).forEach(k=>form[k]='');query.value='';active.value='';},'Student added successfully.');}function remove(record){if(window.confirm(`Delete ${record.name} and all related enrollments?`))run(()=>store.removeStudent(record.id),'Student deleted successfully.');}
</script>
<template><div class="heading"><p class="eyebrow">DIRECTORY</p><h1>Students</h1><p>Add, search and manage student records.</p></div><Feedback :busy="busy" :error="error" :success="success"/><div class="layout"><section class="panel"><h2>Add student</h2><form @submit.prevent="add"><label for="name">Full name</label><input id="name" v-model.trim="form.name" required maxlength="200" placeholder="John"/><label for="sid">Student ID</label><input id="sid" v-model.trim="form.id" required maxlength="200" placeholder="1001"/><label for="phone">Phone number</label><input id="phone" v-model.trim="form.phone" type="tel" required maxlength="200" placeholder="555-1234"/><label for="zip">ZIP code</label><input id="zip" v-model.trim="form.zip" required maxlength="200" placeholder="77001"/><button :disabled="busy">Add student</button></form></section><section class="panel"><h2>Student directory</h2><form @submit.prevent="search"><label for="query">Search by name or ID</label><div class="inline"><input id="query" v-model="query" placeholder="Search students"/><button :disabled="busy">Search</button><button type="button" class="secondary" :disabled="busy" @click="query='';search()">Clear</button></div></form><RecordTable :rows="results" :columns="columns" :busy="busy" deletable @remove="remove"/></section></div></template>
